<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor: <strong><?= V::escape($row['receipt_ref']) ?></strong></p><p>Tanggal: <?= V::escape($row['receipt_date']) ?> · Cabang: <?= V::escape($row['branch_code']) ?> · Gudang: <?= V::escape($row['warehouse_code'] ? $row['warehouse_code'].' - '.$row['warehouse_name'] : 'Belum dialokasikan') ?> · Supplier: <?= V::escape((string)$row['supplier_name']) ?></p><p>Status: <?= V::escape($row['status']) ?> · Referensi: <?= V::escape((string)$row['document_ref']) ?></p><?php if($row['status']==='DRAFT'&&$access->can('inventory.receipt.post')): ?><form method="post" action="<?= $this->url('/inventory/receipt-post') ?>" onsubmit="return confirm('Posting barang masuk? Stok akan bertambah.');"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button button-primary">Posting Barang Masuk</button></form><?php endif ?></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Satuan</th><th>Kuantitas</th><th>Harga</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['item_code'].' - '.$l['item_name']) ?></td><td><?= V::escape($l['unit_name']) ?></td><td><?= number_format((float)$l['quantity'],3,',','.') ?></td><td><?= $l['unit_price']===null?'—':\Hls\Http\View::money($l['unit_price']) ?></td></tr><?php endforeach ?></tbody></table></div></section><a class="button" href="<?= $this->url('/inventory/receipts') ?>">Kembali</a>
